      padding: 0.95rem 1.35rem;
      color: #08111f;
      background: linear-gradient(135deg, var(--accent-strong), var(--accent));
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 14px 34px rgba(143, 183, 255, 0.24);
