    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 700;
    }

    @media (max-width: 24rem) {
      main {
        padding-inline: 0.75rem;
