      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (forced-colors: active) {
      .card,
      .form-field,
      .radio-option,
      button {
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <div id="root"></div>
  </main>

  <script>
    const notificationOptions = ["Email", "SMS", "Push Notifications"];

    function RadioOption({ id, name, value }) {
      return `
        <label class="radio-option" for="${id}">
          <input id="${id}" type="radio" name="${name}" value="${value}" required>
          <span class="radio-label">${value}</span>
        </label>
      `;
    }

    function NotificationForm() {
      const options = notificationOptions
        .map((option, index) => RadioOption({
          id: `notification-${index + 1}`,
          name: "notificationPreference",
          value: option
        }))
        .join("");

      return `
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset>
              <legend>
                How do you prefer to receive notifications?
                <span class="required-note">(required)</span>
              </legend>
              <div class="radio-group">
                ${options}
              </div>
            </fieldset>
          </div>
          <button type="submit">Submit</button>
          <p class="status" id="form-status" role="status" aria-live="polite"></p>
        </form>
      `;
    }

    function App() {
      return `
        <section class="card" aria-labelledby="page-title">
          <p class="eyebrow">Preferences</p>
          <h1 id="page-title">Notification settings</h1>
          <p class="intro">Choose one way for us to contact you about important account activity and updates.</p>
          ${NotificationForm()}
        </section>
      `;
    }

    document.getElementById("root").innerHTML = App();

    document.getElementById("notification-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const form = event.currentTarget;
      const selectedPreference = form.elements.notificationPreference.value;
      const status = document.getElementById("form-status");

      if (!selectedPreference) {
        const firstRadio = form.querySelector('input[name="notificationPreference"]');
        firstRadio.focus();
        status.textContent = "Please choose how you prefer to receive notifications.";
        return;
      }

      status.textContent = `Preference saved: ${selectedPreference}.`;
    });
  </script>
</body>
</html>
