       cursor: pointer;
       box-shadow: 0 14px 34px rgba(143, 183, 255, 0.24);
     }

     button:hover {
       background: var(--accent-strong);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 4px;
     }

     .status {
       min-height: 1.5rem;
       margin: 0;
       color: var(--success);
